WITH base AS (SELECT id, product_name, category, brand, cost, launch_date, tags, supplier_id, CAST(cost AS INT) cost_int FROM products WHERE LOWER(product_name) LIKE '%ack%') SELECT CASE WHEN cost_int >= 64 THEN 'LARGE' ELSE 'SMALL' END AS cost_int_tier, brand, DATE_TRUNC('WEEK', launch_date) AS week_start, COUNT(CASE WHEN category = 'Sports' THEN 1 END) AS sports_count, COUNT(DISTINCT category) AS distinct_categories, SUM(CASE WHEN brand = 'Acme' THEN cost ELSE 0 END) AS acme_cost, COUNT(CASE WHEN category = 'Electronics' THEN 1 END) AS electronics_count, SUM(cost) AS total_cost, SIZE(COLLECT_SET(brand)) AS num_brands FROM base GROUP BY 1, 2, 3 HAVING sports_count < 1000 ORDER BY electronics_count DESC NULLS FIRST
